<script setup lang="ts">
/**
 * Single-line text entry (`design/components/input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, type Ref } from 'vue'

import { Icon, agentFill, agentMember, useControlRef, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/input.module.css'

export type InputType = NonNullable<InputProps['type']>

export interface InputProps {
  ariaDescribedby?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  ariaLabel?: string
  /**
   * The id of a label elsewhere on the page, such as `SettingsRow`'s one label for a whole row.
   */
  ariaLabelledby?: string
  ariaRequired?: boolean
  autoComplete?: string
  /**
   * Native passthrough, for surfaces that already moved the user (a dialog's first field). Never
   * use it to take focus when a page loads.
   */
  autoFocus?: boolean
  /**
   * Shows a clear button while the field is non-empty. Clearing fires `onChange('')`.
   */
  clearable?: boolean
  /**
   * The clear button's accessible name. Defaults to `Clear`. Localized hosts pass their own.
   */
  clearLabel?: string
  /**
   * The native `<input>` itself, for an application binding that must read or restore state only
   * the element has, such as a caret or a selection, without a `querySelector` into the frame.
   * Merged with the member's own ref, so both get the same node, and `null` on unmount. Accepts
   * callback and object refs.
   */
  controlRef?: Ref<HTMLInputElement | null>
  defaultValue?: string
  disabled?: boolean
  /**
   * The text is typed exactly: nothing corrects it, capitalises it or checks its spelling. For
   * text that must match letter for letter, such as a typed confirmation's phrase, because a
   * correction can change it while it is typed.
   */
  exact?: boolean
  /**
   * Leading, decorative.
   */
  icon?: IconRole
  id?: string
  invalid?: boolean
  max?: number
  maxLength?: number
  /**
   * `type="number"` only. Native passthrough, so the platform handles clamping and stepping.
   */
  min?: number
  name?: string
  placeholder?: string
  /**
   * Static text inside the frame, such as a currency mark, a unit or a domain. Strings only,
   * because a node here would duplicate `trailing`. They are `aria-hidden` and not part of the
   * value, so a unit that matters belongs in the label or description. The affix is only its
   * visual form.
   */
  prefix?: string
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  step?: number
  suffix?: string
  type?: 'number' | 'search' | 'text' | 'email' | 'password' | 'url' | 'tel'
  value?: string
}

defineOptions({ name: 'Input', inheritAttrs: false })

const props = withDefaults(defineProps<InputProps>(), {
  ariaRequired: undefined,
  autoFocus: false,
  clearable: false,
  clearLabel: 'Clear',
  disabled: false,
  exact: false,
  invalid: false,
  readOnly: false,
  size: 'md',
  type: 'text',
})
const emit = defineEmits<{
  blur: [event: FocusEvent]
  change: [value: string, event: Event]
  compositionEnd: [event: CompositionEvent]
  compositionStart: [event: CompositionEvent]
  focus: [event: FocusEvent]
  select: [event: Event]
}>()
defineSlots<{ trailing?: (props: Record<string, never>) => unknown }>()
const draft = ref(props.defaultValue ?? '')
const [control, attachControl] = useControlRef(() => props.controlRef)
const current = computed(() => props.value ?? draft.value)
const showClear = computed(
  () => props.clearable && current.value !== '' && !props.disabled && !props.readOnly,
)
const effect1 = () => {
  props.autoFocus && control.value?.focus()
}
onMounted(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Input',
    element: () => control.value,
    state: () => ({
      value: current.value,
      disabled: props.disabled,
      invalid: props.invalid,
      readonly: props.readOnly,
    }),
    actions: {
      fill: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (props.type === 'password')
              throw new Error('A person types a password; an agent does not.')
            if (props.readOnly) throw new Error('The field is read-only.')
            agentFill(control.value, value)
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The field is read-only.')
          agentFill(control.value, '')
        })(),
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    :class="styles.field"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    data-member="input"
    @mousedown="
      !$event
        .composedPath()
        .some(
          (node) =>
            'nodeName' in node &&
            ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(String(node.nodeName)),
        ) && ($event.preventDefault(), control?.focus())
    "
  >
    <!-- leading -->
    <span v-if="icon !== undefined" :class="styles.leading">
      <Icon :name="icon" :size="size" />
    </span>
    <!-- affix -->
    <span v-if="prefix !== undefined" :class="styles.affix" aria-hidden="true">
      {{ prefix }}
    </span>
    <!-- input -->
    <input
      :ref="attachControl"
      :class="styles.input"
      :type="type"
      :value="current"
      :placeholder="placeholder"
      :disabled="disabled"
      :readonly="readOnly"
      :min="min"
      :max="max"
      :step="step"
      :name="name"
      :id="id"
      :autocomplete="autoComplete"
      :autocorrect="exact ? 'off' : undefined"
      :autocapitalize="exact ? 'off' : undefined"
      :spellcheck="exact ? 'false' : undefined"
      :maxlength="maxLength"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      :aria-invalid="invalid ? true : undefined"
      @input="((draft = control?.value ?? ''), emit('change', draft, $event))"
      @blur="emit('blur', $event)"
      @focus="emit('focus', $event)"
      @select="emit('select', $event)"
      @compositionstart="emit('compositionStart', $event)"
      @compositionend="emit('compositionEnd', $event)"
    />
    <!-- affix -->
    <span v-if="suffix !== undefined" :class="styles.affix" aria-hidden="true">
      {{ suffix }}
    </span>
    <!-- clear -->
    <button
      v-if="showClear"
      :class="styles.clear"
      type="button"
      :aria-label="clearLabel"
      @click="((draft = ''), emit('change', '', $event), control?.focus())"
    >
      <Icon name="clear" :size="size" />
    </button>
    <!-- trailing -->
    <span v-if="$slots.trailing" :class="styles.trailing">
      <slot name="trailing" />
    </span>
  </div>
</template>
